function overlap(zones){ if(!zones||!zones.length) return {error:'请至少提供一个时区'};
  var lo=-Infinity, hi=Infinity;
  for(var i=0;i<zones.length;i++){ var z=zones[i]; var a=z.start-(z.offset||0), b=z.end-(z.offset||0); if(a>lo) lo=a; if(b<hi) hi=b; }
  if(!(lo<hi)) return {overlap:false, start:null, end:null};
  return {overlap:true, start:lo, end:hi}; }
var EXPORTS={overlap:overlap};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ZonePlanForgePure = EXPORTS; }
